?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><style>:root{--p:#635bff;--ink:#171923;--muted:#7a8191;--line:#e6e8ee;--bg:#f7f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.tool-page{width:min(760px,calc(100% - 24px));margin:0 auto;padding:16px 0 24px}.tool-page .tool-seo-intro{display:none!important}.intro{text-align:center;margin:0 0 12px}.intro h1{margin:0;font-size:clamp(26px,4vw,36px);letter-spacing:-1.5px;line-height:1.05}.intro h1 span{color:var(--p)}.intro p{margin:6px 0 0;color:var(--muted);font-size:9px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:0 10px 30px rgba(23,26,36,.05)}.bar{height:44px;padding:0 12px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.state{display:flex;align-items:center;gap:8px;font-size:8px;font-weight:800}.state i{width:7px;height:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px #dcfce7}.bar button{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 9px;font-size:8px;font-weight:800;color:#555d6d;cursor:pointer}.area{padding:10px}.drop,.viewer{position:relative;border:1px solid var(--line);border-radius:13px;overflow:hidden}.drop{min-height:255px;display:grid;place-items:center;text-align:center;padding:18px;background:#fafbfe}.drop.drag{border-color:var(--p);background:#f7f6ff}.upload{width:50px;height:50px;margin:auto;border-radius:14px;display:grid;place-items:center;background:#eeecff;color:var(--p);font-size:24px;font-weight:900}.drop h2{margin:9px 0 5px;font-size:18px;letter-spacing:-.35px}.drop p{margin:0 auto 13px;max-width:350px;color:var(--muted);font-size:9px;line-height:1.55}.choose{display:inline-flex;align-items:center;gap:7px;padding:10px 16px;border-radius:10px;background:var(--p);color:#fff;font-size:9px;font-weight:800;cursor:pointer}.meta{margin-top:8px;color:#a0a6b2;font-size:7px}.viewer{display:none;min-height:0;padding:0;align-items:center;justify-content:center;background:repeating-conic-gradient(#eef1f5 0 25%,#fafbfc 0 50%) 50%/18px 18px}.stack{position:relative;display:block;max-width:100%;max-height:420px;overflow:hidden}.stack canvas{display:block;width:auto;height:auto;max-width:100%;max-height:420px}.result-layer{position:absolute;inset:0}.original-layer{position:absolute;inset:0;z-index:2;overflow:hidden;clip-path:inset(0 0 0 0)}.magic{position:absolute;inset:0;display:none;pointer-events:none;align-items:center;justify-content:center;background:radial-gradient(circle at center,rgba(99,91,255,.08),transparent 55%);z-index:5;contain:paint}.processing .magic{display:flex}.magic-line{position:absolute;left:6%;right:6%;height:2px;background:linear-gradient(90deg,transparent,#756dff 20%,#fff 50%,#756dff 80%,transparent);box-shadow:0 0 18px rgba(99,91,255,.7);animation:magic 1.55s ease-in-out infinite;will-change:transform,opacity}.magic-ring{width:92px;height:92px;border:1px solid rgba(99,91,255,.3);border-radius:50%;box-shadow:0 0 24px rgba(99,91,255,.18);animation:ring 1.55s ease-in-out infinite;will-change:transform,opacity}.magic:after{content:"";position:absolute;width:10px;height:10px;border-radius:50%;background:#fff;box-shadow:0 0 14px #8d85ff,0 0 30px rgba(117,109,255,.45);animation:spark 1.55s ease-in-out infinite;will-change:transform,opacity}@keyframes magic{0%{transform:translate3d(0,-42%,0);opacity:0}18%{opacity:1}50%{transform:translate3d(0,0,0);opacity:1}82%{opacity:1}100%{transform:translate3d(0,42%,0);opacity:0}}@keyframes ring{0%,100%{transform:scale(.76);opacity:.28}50%{transform:scale(1.08);opacity:.92}}@keyframes spark{0%{transform:translate3d(0,-75px,0) scale(.5);opacity:0}22%{opacity:.9}50%{transform:translate3d(0,0,0) scale(1);opacity:1}78%{opacity:.85}100%{transform:translate3d(0,75px,0) scale(.5);opacity:0}}.wipe{animation:backgroundWipe 2.4s cubic-bezier(.22,.61,.36,1) forwards}@keyframes backgroundWipe{0%{clip-path:inset(0 0 0 0)}22%{clip-path:inset(0 0 0 12%)}55%{clip-path:inset(0 0 0 58%)}82%{clip-path:inset(0 0 0 88%)}100%{clip-path:inset(0 0 0 100%)}}.progress{position:absolute;left:12px;right:12px;bottom:12px;padding:9px 11px;border-radius:10px;background:rgba(20,23,31,.92);color:#fff;backdrop-filter:blur(8px);z-index:7}.prow{display:flex;justify-content:space-between;font-size:7px;font-weight:800}.track{height:4px;margin-top:6px;border-radius:99px;background:#323642;overflow:hidden}.track i{display:block;width:0;height:100%;background:linear-gradient(90deg,var(--p),#9b92ff);transition:width .25s ease}.actions{display:none;gap:7px;padding-top:9px}.actions button{flex:1;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px;font-size:8px;font-weight:800;cursor:pointer;color:#555d6d}.actions .primary{background:#171923;border-color:#171923;color:#fff}@media(max-width:600px){.tool-page{width:calc(100% - 14px);padding-top:12px}.intro h1{font-size:26px}.drop{min-height:230px}.viewer canvas{max-height:360px}.stack{max-height:360px}.actions{flex-direction:column}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="tool-page"><div class="intro"><h1>Background <span>Remover</span></h1><p>Remove the background from any image in your browser.</p></div><section class="card"><div class="bar"><div class="state"><i></i><span id="status">Ready</span></div><button id="new" type="button">New image</button></div><div class="area"><div class="drop" id="drop"><div><div class="upload">✂</div><h2>Drop an image here</h2><p>Choose a photo and SmartToolz will remove the background automatically.</p><label class="choose">Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="meta">PNG • JPG • WebP</div></div></div><div class="viewer" id="viewer"><div class="stack" id="stack"><div class="result-layer"><canvas id="resultCanvas"></canvas></div><div class="original-layer" id="originalLayer"><canvas id="preview"></canvas></div></div><div class="magic"><div class="magic-ring"></div><div class="magic-line"></div></div><div class="progress" id="progress"><div class="prow"><span>Removing background…</span><span id="pct">0%</span></div><div class="track"><i id="fill"></i></div></div></div><div class="actions" id="actions"><button id="again" type="button">Try another</button><button id="download" class="primary" type="button">Download PNG</button></div></div></section></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id),picker=$('picker'),drop=$('drop'),viewer=$('viewer'),preview=$('preview'),pctx=preview.getContext('2d'),resultCanvas=$('resultCanvas'),rctx=resultCanvas.getContext('2d'),originalLayer=$('originalLayer'),progress=$('progress'),fill=$('fill'),pct=$('pct'),status=$('status'),actions=$('actions');let outUrl='',sourceUrl='',lastProgress=0,lastProgressAt=0;function reset(){picker.value='';drop.style.display='grid';viewer.style.display='none';viewer.classList.remove('processing');originalLayer.classList.remove('wipe');originalLayer.style.clipPath='inset(0 0 0 0)';progress.style.display='block';actions.style.display='none';status.textContent='Ready';if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outUrl='';sourceUrl='';fill.style.width='0%';pct.textContent='0%'}function loadImage(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src})}function paintExact(target,ctx,img){target.width=img.naturalWidth;target.height=img.naturalHeight;ctx.clearRect(0,0,target.width,target.height);ctx.drawImage(img,0,0,target.width,target.height)}async function process(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';viewer.style.display='flex';viewer.classList.add('processing');originalLayer.classList.remove('wipe');originalLayer.style.clipPath='inset(0 0 0 0)';actions.style.display='none';progress.style.display='block';fill.style.width='4%';pct.textContent='4%';status.textContent='Removing background';sourceUrl=URL.createObjectURL(file);try{const source=await loadImage(sourceUrl);paintExact(preview,pctx,source);const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(name,current,total)=>{const now=performance.now();const p=total?Math.max(5,Math.min(96,Math.round(current/total*91)+5)):8;if(p!==lastProgress&&(now-lastProgressAt>120||p>=96)){lastProgress=p;lastProgressAt=now;requestAnimationFrame(()=>{fill.style.width=p+'%';pct.textContent=p+'%'})}}});if(outUrl)URL.revokeObjectURL(outUrl);outUrl=URL.createObjectURL(blob);const result=await loadImage(outUrl);paintExact(resultCanvas,rctx,result);fill.style.width='100%';pct.textContent='100%';progress.style.display='none';viewer.classList.remove('processing');status.textContent='Background removed';originalLayer.classList.add('wipe');setTimeout(()=>{actions.style.display='flex'},2450)}catch(err){console.error(err);reset();status.textContent='Could not process image'}}picker.onchange=()=>{const f=picker.files?.[0];picker.value='';process(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');process(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outUrl)return;const a=document.createElement('a');a.href=outUrl;a.download='smarttoolz-background-removed.png';document.body.appendChild(a);a.click();a.remove()};window.addEventListener('beforeunload',()=>{if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>